import React from 'react'
import {
  Card,
  CardHeader,
  CardContent,
  CardDescription,
  CardTitle,
} from "@/components/ui/card"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
//font
import {DM_Sans} from "next/font/google";

const DMsansFont = DM_Sans({
  subsets: ["latin"],
})

const HeartLine = () => {
  
  return (
      <div className="flex flex-col min-h-screen bg-white p-5">
        <div className="navbar bg-base-100">
          <div className="navbar-start"></div>
          <h1 className={` ${DMsansFont.className} navbar-center text-5xl text-[#CE2746]`}>Heart Line</h1>
          <div className="navbar-end"></div>
        </div>

      <section className='flex flex-row justify-center'>
        <div className='container p-6'>
          <div className="misc-heading">
            <h1 className={`${DMsansFont.className} text-[#3B3D40] pb-6 scroll-m-20 text-start text-4xl font-medium tracking-tight text-balance`}>
              We have found a great match for you!
            </h1>
          </div>
          <div className="flex flex-row therapist-card justify-start">
            <Card className="rounded-[85px] w-full pl-10 p-6 border-2 border-[#89DDD9] shadow-[0_4px_4px_0_#89DDD9]/50 bg-[#89DDD9]/10">
              <CardHeader className="flex flex-row items-center pl-30 pb-0">
                <Avatar className="h-28 w-28">
                  {/* Uncomment this if you have an image */}
                  {/* <AvatarImage src="https://example.com/image.jpg" alt="Dr. Aisha Patel" /> */}
                  <AvatarFallback className="bg-gray-400 text-white font-semibold text-xl">AP</AvatarFallback>
                </Avatar>
                <div>
                  <CardTitle className="text-4xl text-[#3B3D40] font-bold pb-2">Dr. Aisha Patel</CardTitle>
                  <CardDescription className="text-[#3B3D40] text-xl italic">
                    Dr. Patel creates a supportive environment for exploring patterns and building self-worth.
                  </CardDescription>
                </div>
              </CardHeader>
              <CardContent className="pt-0 pb-0 pl-30">
                <p className={`${DMsansFont.className} text-[#3B3D40] text-xl mt-4 pl-6`}><strong>Qualification:</strong> Blah Blah Blah Degree</p>
                <p className={`${DMsansFont.className} text-[#3B3D40] text-xl mt-2 pl-6`}><strong>Approach:</strong> Person-Centered, Psychodynamic</p>
                <p className={`${DMsansFont.className} text-[#3B3D40] text-xl mt-2 pl-6`}><strong>Has helped people with :</strong> Relationship Issues, Self-Esteem</p>
              </CardContent>
            </Card>
          </div>
        </div>
      </section>

        <section className='review-section'>
          <div className='review-headin'>
             <h3 className={`${DMsansFont.className} scroll-m-20 text-[#3B3D40] text-2xl font-semibold tracking-tight`}>
                Here’s what people had to say:
              </h3>
          </div>
          <Card className='bg-transparent shadow-none border-none'>
            <CardContent>
              <blockquote className={`${DMsansFont.className} text-[#3B3D40] mt-6 pl-6 italic`}>
                &quot;Dr. Patel has a way of asking questions that linger in your mind long after the session. 
                Her approach helped me realize how much of my low self-esteem came from childhood dynamics I never fully processed. 
                I feel like I&apos;m finally rewriting my own story.&quot;
              </blockquote>
            </CardContent>
          </Card>
        </section>

      </div>
    );
}

export default HeartLine